"""Merging helpers for imported contact lists."""
from .models import Contact


def dedupe(contacts: list[Contact]) -> list[Contact]:
    """Return the list without duplicate people."""
    seen_emails = set()
    result = []

    for contact in contacts:
        normalized_email = contact.email.lower().strip()

        if not normalized_email or normalized_email not in seen_emails:
            result.append(contact)
            if normalized_email:
                seen_emails.add(normalized_email)

    return result
